using System;using System.Collections.Generic;using HarmonyLib;using RimWorld;using RimWorld.Planet;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static partial class CelestialLightTravel {
  public const int DepartTicks=42,ArriveTicks=24;
  public static string Problem(Pawn p){if(p==null||!IncarnateTransit.Active(p)||!ElementalTeaching.Ready(p)||!ElementalCombatPolicy.Controlled(p))return "Requires a conscious player-controlled Celestial or Thunder Incarnate on a map.";if(CelestialAscendant.Busy(p)||ElementalAnimationBridge.Controlled(p)||ElementalTeachingSession.Busy(p)||ElementalBestow.Busy(p)||HediffComp_ElementalTransform.Transforming(p)||AzureEvolution.Evolving(p))return "Finish the current action before traveling.";if(p.carryTracker!=null&&p.carryTracker.CarriedThing!=null)return "Put down the carried pawn or item before traveling.";return null;}
  public static bool DestinationAllowed(PlanetTile origin,PlanetTile destination){if(!origin.Valid||!destination.Valid||origin.Layer!=destination.Layer)return false;var parent=Find.WorldObjects.MapParentAt(destination);return parent!=null&&parent.HasMap||Find.WorldGrid[destination].PrimaryBiome!=BiomeDefOf.Ocean;}
  public static bool DepartureReserved(PlanetTile tile){foreach(var map in Find.Maps)foreach(var p in map.mapPawns.SpawnedPawnsInFaction(Faction.OfPlayer)){if(p.CurJobDef==null||(p.CurJobDef.defName!=CelestialAscendant.Depart&&p.CurJobDef.defName!=IncarnateTransit.Depart))continue;if(IncarnateTransit.Destination(p)==tile)return true;}return false;}
  public static bool TryDepart(Pawn p,PlanetTile destination){return TryDepart(p,destination,IntVec3.Invalid,Find.TickManager.CurTimeSpeed==TimeSpeed.Paused);}
  public static bool TryDepart(Pawn p,PlanetTile destination,IntVec3 cell,bool restorePause){return TryDepart(p,destination,cell,restorePause,false);}
  public static bool TryDepart(Pawn p,PlanetTile destination,IntVec3 cell,bool restorePause,bool exactLanding){if(Problem(p)!=null||!DestinationAllowed(p.Map.Tile,destination))return false;IncarnateTransit.Destination(p,destination);var job=JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(IncarnateTransit.DepartJob(p)),p.Position,cell);job.count=(restorePause?1:0)|(exactLanding?2:0);job.playerForced=true;p.jobs.StartJob(job,JobCondition.InterruptForced,cancelBusyStances:true);if(p.CurJob==job){if(Find.TickManager.CurTimeSpeed==TimeSpeed.Paused)Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return true;}IncarnateTransit.Destination(p,PlanetTile.Invalid);return false;}
  public static bool Launch(Pawn p,PlanetTile destination){return Launch(p,destination,p.CurJob==null?IntVec3.Invalid:p.CurJob.targetB.Cell,p.CurJob!=null&&(p.CurJob.count&1)!=0);}
  public static bool Launch(Pawn p,PlanetTile destination,IntVec3 arrivalCell,bool restorePause){return Launch(p,destination,arrivalCell,restorePause,p.CurJob!=null&&(p.CurJob.count&2)!=0);}
  public static bool Launch(Pawn p,PlanetTile destination,IntVec3 arrivalCell,bool restorePause,bool exactLanding){
   if(p==null||!p.Spawned||!IncarnateTransit.Active(p)||!ElementalTeaching.Ready(p)||!DestinationAllowed(p.Map.Tile,destination))return false;Map map=p.Map;IntVec3 at=p.Position;if(destination==map.Tile){IntVec3 chosen=arrivalCell;if(exactLanding){if(!LandingSafe(chosen,map,IncarnateTransit.Thunder(p)))return false;}else if(!AutoCell(map,chosen,out chosen))return false;bool draft=p.Drafted;p.jobs.StopAll();p.Position=chosen;CompleteArrival(p,map,chosen,restorePause,draft);return true;}var flight=(WorldObject_CelestialLightTravel)WorldObjectMaker.MakeWorldObject(DefDatabase<WorldObjectDef>.GetNamed(IncarnateTransit.Thunder(p)?"EH_ThunderTravel":"EH_CelestialLightTravel"));flight.Tile=map.Tile;flight.destination=destination;flight.arrivalCell=arrivalCell;flight.originCell=at;flight.restorePause=restorePause;flight.draftOnArrival=p.Drafted;flight.automatic=true;flight.exactLanding=exactLanding;flight.SetFaction(p.Faction);p.jobs.StopAll();p.DeSpawn();
   if(!flight.Container.TryAdd(p)){GenSpawn.Spawn(p,at,map);if(p.drafter!=null)p.drafter.Drafted=flight.draftOnArrival;return false;}try{Find.WorldObjects.Add(flight);}catch(Exception e){flight.Container.Remove(p);GenSpawn.Spawn(p,at,map);if(p.drafter!=null)p.drafter.Drafted=flight.draftOnArrival;Log.Error("[Elemental Hearts] Light Travel rolled back: "+e);return false;}Find.WorldSelector.ClearSelection();flight.BeginArrival();return true;
  }
  public static Map PrepareMap(PlanetTile destination){return PrepareMap(destination,false);}
  public static Map PrepareMap(PlanetTile destination,bool thunder){MapParent parent=Find.WorldObjects.MapParentAt(destination);if(parent==null){parent=(MapParent)WorldObjectMaker.MakeWorldObject(DefDatabase<WorldObjectDef>.GetNamed(thunder?"EH_ThunderLandingSite":"EH_CelestialLandingSite"));parent.Tile=destination;parent.SetFaction(Faction.OfPlayer);Find.WorldObjects.Add(parent);}bool generated=!parent.HasMap;Map map=parent.HasMap?parent.Map:GetOrGenerateMapUtility.GetOrGenerateMap(destination,Find.World.info.initialMapSize,parent.def);if(generated&&map!=null){var spot=DropCellFinder.GetBestShuttleLandingSpot(map,Faction.OfPlayer);if(spot.IsValid)FloodFillerFog.FloodUnfog(spot,map);}return map;}
  public static bool Safe(IntVec3 cell,Map map){return LandingSafe(cell,map,false);}
  public static bool LandingSafe(IntVec3 cell,Map map,bool allowFog){if(map==null||!cell.InBounds(map)||!cell.Standable(map)||!allowFog&&cell.Fogged(map)||cell.GetTerrain(map).passability==Traversability.Impassable)return false;var door=cell.GetEdifice(map) as Building_Door;if(door!=null&&!door.Open)return false;foreach(var thing in cell.GetThingList(map))if(thing is Pawn||thing is Fire||thing is Building_Trap)return false;return true;}
  public static void CompleteArrival(Pawn pawn,Map map,IntVec3 cell,bool pause,bool drafted){pawn.Notify_Teleported();if(pawn.drafter!=null)pawn.drafter.Drafted=drafted;if(IncarnateTransit.Thunder(pawn)){foreach(var near in GenRadial.RadialCellsAround(cell,1.5f,true))if(near.InBounds(map))map.fogGrid.Unfog(near);map.GetComponent<MapComponent_IncarnateVfx>().ResetTrack(pawn);}var job=JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(IncarnateTransit.ArriveJob(pawn)),cell);job.count=pause?1:0;pawn.jobs.StartJob(job,JobCondition.InterruptForced,cancelBusyStances:true);if(pause)Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;if(Find.CurrentMap!=map||WorldRendererUtility.WorldSelected){Current.Game.CurrentMap=map;CameraJumper.TryJump(cell,map);}Find.Selector.ClearSelection();Find.Selector.Select(pawn);}
  public static bool AutoCell(Map map,IntVec3 preferred,out IntVec3 result){result=IntVec3.Invalid;if(map==null)return false;var center=preferred.IsValid&&preferred.InBounds(map)?preferred:DropCellFinder.TradeDropSpot(map);if(!center.InBounds(map))center=map.Center;int visited=0;foreach(var cell in GenRadial.RadialCellsAround(center,14,true)){if(++visited>640)break;if(Safe(cell,map)){result=cell;return true;}}int cells=map.cellIndices.NumGridCells,limit=Math.Min(2048,cells);for(int i=0;i<limit;i++){var cell=map.cellIndices.IndexToCell((int)((long)i*cells/limit));if(Safe(cell,map)){result=cell;return true;}}return false;}
 }
 public sealed class JobDriver_CelestialDepart:JobDriver {
  public int elapsed;bool launched;PlanetTile destination=PlanetTile.Invalid;int beam,seal;
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  public override void ExposeData(){base.ExposeData();Scribe_Values.Look(ref elapsed,"EH_lightDepartElapsed");Scribe_Values.Look(ref launched,"EH_lightDepartLaunched");Scribe_Values.Look(ref destination,"EH_lightDepartDestination",PlanetTile.Invalid);}
  bool Valid(){return !launched&&pawn.CurJob==job&&IncarnateTransit.Active(pawn)&&ElementalTeaching.Ready(pawn)&&pawn.Position==job.targetA.Cell&&!ElementalAnimationBridge.ExternallyControlled(pawn);}
  void Cleanup(){if(pawn.Spawned){IncarnateTransit.Stop(pawn,beam);IncarnateTransit.Stop(pawn,seal);}IncarnateTransit.Destination(pawn,PlanetTile.Invalid);if(!launched&&(job.count&1)!=0)Find.TickManager.Pause();}
  protected override IEnumerable<Toil> MakeNewToils(){AddFinishAction(condition=>Cleanup());this.FailOn(()=>!Valid());var departure=new Toil();departure.defaultCompleteMode=ToilCompleteMode.Never;departure.handlingFacing=true;departure.initAction=()=>{pawn.pather.StopDead();pawn.stances.CancelBusyStanceHard();if(!destination.Valid){destination=IncarnateTransit.Destination(pawn);}if(!destination.Valid){EndJobWith(JobCondition.Incompletable);return;}beam=IncarnateTransit.Emit(pawn,CelestialEffect.DepartureBeam,CelestialLightTravel.DepartTicks,2.8f,8,elapsed);seal=IncarnateTransit.Emit(pawn,CelestialEffect.SolarSeal,CelestialLightTravel.DepartTicks,3,3,elapsed);if(elapsed==0)ElementalAudio.Ability(pawn,ElementalSound.Charge);};departure.tickAction=()=>{pawn.pather.StopDead();if(++elapsed<CelestialLightTravel.DepartTicks)return;launched=true;var next=destination;var cell=job.targetB.Cell;bool pause=(job.count&1)!=0;IncarnateTransit.Emit(pawn,CelestialEffect.TravelMotes,36,2.5f,2.5f);ElementalAudio.Play(pawn,"EH_TransformLock");if(!CelestialLightTravel.Launch(pawn,next,cell,pause)){bool retry=(job.count&2)!=0&&pawn.Spawned&&next==pawn.Map.Tile&&!CelestialLightTravel.LandingSafe(cell,pawn.Map,IncarnateTransit.Thunder(pawn));launched=false;if(pawn.CurJob==job)EndJobWith(JobCondition.Incompletable);if(retry&&CelestialLightTravel.Problem(pawn)==null)CelestialLightTravel.QueuePlan(pawn,next,true,pause);}};yield return departure;}
 }
 public sealed class JobDriver_CelestialArrive:JobDriver {
  public int elapsed;int beam,ring,motes;
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  public override void ExposeData(){base.ExposeData();Scribe_Values.Look(ref elapsed,"EH_lightArriveElapsed");}
  void Cleanup(){if(pawn.Spawned){IncarnateTransit.Stop(pawn,beam);IncarnateTransit.Stop(pawn,ring);IncarnateTransit.Stop(pawn,motes);}if((job.count&1)!=0)Find.TickManager.Pause();}
  protected override IEnumerable<Toil> MakeNewToils(){AddFinishAction(condition=>Cleanup());this.FailOn(()=>!IncarnateTransit.Active(pawn)||!ElementalTeaching.Ready(pawn)||pawn.Position!=job.targetA.Cell||ElementalAnimationBridge.ExternallyControlled(pawn));var arrival=new Toil();arrival.defaultCompleteMode=ToilCompleteMode.Never;arrival.handlingFacing=true;arrival.initAction=()=>{pawn.pather.StopDead();pawn.stances.CancelBusyStanceHard();beam=IncarnateTransit.Emit(pawn,CelestialEffect.ArrivalBeam,CelestialLightTravel.ArriveTicks,3.5f,10,elapsed);ring=IncarnateTransit.Emit(pawn,CelestialEffect.ArrivalRing,CelestialLightTravel.ArriveTicks,5,5,elapsed);motes=IncarnateTransit.Emit(pawn,CelestialEffect.TravelMotes,CelestialLightTravel.ArriveTicks,3,3,elapsed);if(IncarnateTransit.Thunder(pawn))IncarnateVfx.Track(pawn);else pawn.Map.GetComponent<MapComponent_CelestialVfx>().Track(pawn);if(elapsed==0)ElementalAudio.Ability(pawn,ElementalSound.Impact);};arrival.tickAction=()=>{pawn.pather.StopDead();if(++elapsed>=CelestialLightTravel.ArriveTicks)ReadyForNextToil();};yield return arrival;}
 }
 [HarmonyPatch(typeof(MapParent),"CheckRemoveMapNow")]
 public static class TravelMapLifetime {
  public static bool Reserved(PlanetTile tile){if(CelestialLightTravel.PlanningAt(tile)||CelestialLightTravel.DepartureReserved(tile))return true;foreach(var item in Find.WorldObjects.AllWorldObjects){var travel=item as WorldObject_CelestialLightTravel;if(travel!=null&&travel.Container.Count>0&&(travel.Tile==tile||travel.destination==tile))return true;}return false;}
  public static bool Prefix(MapParent __instance){return !__instance.HasMap||!Reserved(__instance.Tile);}
 }
 public sealed class CelestialLandingSite:MapParent {
  public override bool ShouldRemoveMapNow(out bool alsoRemoveWorldObject){alsoRemoveWorldObject=true;if(!HasMap||Map.mapPawns.AnyPawnBlockingMapRemoval||CelestialLightTravel.PlanningAt(Tile)||CelestialLightTravel.DepartureReserved(Tile))return false;foreach(var world in Find.WorldObjects.AllWorldObjects){var travel=world as WorldObject_CelestialLightTravel;if(travel!=null&&travel.Container.Count>0&&(travel.destination==Tile||travel.Tile==Tile))return false;}return true;}
 }
 public sealed class WorldObject_CelestialLightTravel:WorldObject,IThingHolder {
  ThingOwner inner;public PlanetTile destination;public int remaining=1;bool arrivalQueued,awaitingLanding;public bool automatic,restorePause,draftOnArrival,exactLanding;public IntVec3 arrivalCell=IntVec3.Invalid,originCell=IntVec3.Invalid;
  public ThingOwner Container{get{return inner;}}
  public bool IsThunder{get{return def.defName=="EH_ThunderTravel";}}
  public WorldObject_CelestialLightTravel(){inner=new ThingOwner<Thing>(this,false,LookMode.Deep);}
  public override Vector3 DrawPos{get{return Find.WorldGrid.GetTileCenter(destination.Valid?destination:Tile);}}
  public override void ExposeData(){base.ExposeData();Scribe_Deep.Look(ref inner,"EH_lightPassenger",this);Scribe_Values.Look(ref destination,"EH_lightDestination");Scribe_Values.Look(ref remaining,"EH_lightRemaining",1);Scribe_Values.Look(ref awaitingLanding,"EH_lightAwaitingLanding");Scribe_Values.Look(ref automatic,"EH_lightAutomatic");Scribe_Values.Look(ref restorePause,"EH_lightRestorePause");Scribe_Values.Look(ref draftOnArrival,"EH_lightDraftOnArrival");Scribe_Values.Look(ref exactLanding,"EH_lightExactLanding");Scribe_Values.Look(ref arrivalCell,"EH_lightArrivalCell",IntVec3.Invalid);Scribe_Values.Look(ref originCell,"EH_lightOriginCell",IntVec3.Invalid);if(Scribe.mode==LoadSaveMode.PostLoadInit){if(inner==null)inner=new ThingOwner<Thing>(this,false,LookMode.Deep);arrivalQueued=false;remaining=Math.Max(0,Math.Min(1,remaining));if(automatic)awaitingLanding=false;}}
  protected override void Tick(){base.Tick();if(remaining>0)remaining--;if(remaining==0&&!arrivalQueued&&!awaitingLanding)QueueArrival();}
  public override string GetInspectString(){return (IsThunder?"Thunder Travel":"Light Travel")+" — no cost\n"+(remaining>0?(IsThunder?"Crossing the world as lightning.":"Crossing the world as sunlight."):"Awaiting safe arrival. Land automatically, choose a precise cell, or return to origin.");}
  public override IEnumerable<Gizmo> GetGizmos(){foreach(var g in base.GetGizmos())yield return g;yield return new Command_Action{defaultLabel="Land safely",defaultDesc="Automatically find a safe arrival cell. The original pawn stays held until placement succeeds.",icon=IncarnateTransit.Icon(IsThunder),action=()=>{automatic=true;exactLanding=false;if(!arrivalQueued)QueueArrival();}};yield return new Command_Action{defaultLabel="Choose landing cell",defaultDesc="Choose an exact safe arrival cell. Canceling retains the original pawn in transit.",icon=IncarnateTransit.Icon(IsThunder),action=()=>{automatic=false;if(!arrivalQueued)QueueArrival();}};yield return new Command_Action{defaultLabel="Return to origin",defaultDesc="Return to the departure location for free, using a nearby safe cell if necessary.",icon=IncarnateTransit.Icon(IsThunder),action=ReturnToOrigin};}
  public void ReturnToOrigin(){if(arrivalQueued)return;destination=Tile;arrivalCell=originCell;automatic=true;exactLanding=false;remaining=0;awaitingLanding=false;QueueArrival();}
  public Map PrepareDestination(){return CelestialLightTravel.PrepareMap(destination,IsThunder);}
  public void BeginArrival(){remaining=0;if(!arrivalQueued)QueueArrival();}
  void QueueArrival(){if(arrivalQueued||inner.Count!=1||!destination.Valid)return;arrivalQueued=true;awaitingLanding=true;var parent=Find.WorldObjects.MapParentAt(destination);if(parent!=null&&parent.HasMap){ResolveArrival(parent.Map);return;}LongEventHandler.QueueLongEvent(()=>{try{Map map=PrepareDestination();LongEventHandler.ExecuteWhenFinished(()=>ResolveArrival(map));}catch(Exception e){arrivalQueued=false;Log.Error("[Elemental Hearts] Travel retained passenger safely: "+e);Messages.Message("Arrival unavailable. Use Land safely or Return to origin.",MessageTypeDefOf.RejectInput,false);}},"GeneratingMap",true,null);}
  void ResolveArrival(Map map){arrivalQueued=false;if(inner.Count!=1||!Find.WorldObjects.AllWorldObjects.Contains(this)||map==null)return;if(automatic){if(exactLanding){if(CelestialLightTravel.LandingSafe(arrivalCell,map,IsThunder)&&TryLand(arrivalCell,map))return;automatic=false;Messages.Message("The selected landing cell became blocked. Choose another cell; the traveler is safe in transit.",MessageTypeDefOf.NeutralEvent,false);}else{IntVec3 cell;if(CelestialLightTravel.AutoCell(map,arrivalCell,out cell)&&TryLand(cell,map))return;automatic=false;}}SelectLanding(map);}
  void SelectLanding(Map map){Find.TickManager.Pause();Current.Game.CurrentMap=map;CameraJumper.TryJump(arrivalCell.IsValid&&arrivalCell.InBounds(map)?arrivalCell:map.Center,map);var marks=new List<IntVec3>{IntVec3.Invalid};var target=TargetingParameters.ForCell();target.validator=t=>Find.CurrentMap==map&&t.Cell.InBounds(map);Func<LocalTargetInfo,bool> valid=t=>Find.CurrentMap==map&&!WorldRendererUtility.WorldSelected&&CelestialLightTravel.LandingSafe(t.Cell,map,IsThunder);bool landed=false;Find.Targeter.BeginTargeting(target,t=>{if(!valid(t))return;landed=TryLand(t.Cell,map);},t=>{if(Find.CurrentMap==map&&t.Cell.InBounds(map)){marks[0]=t.Cell;GenDraw.DrawFieldEdges(marks,valid(t)?Color.yellow:Color.red);}},valid,null,()=>{if(!landed&&inner.Count==1&&Find.WorldObjects.AllWorldObjects.Contains(this)){CameraJumper.TryJump(new GlobalTargetInfo(destination.Valid?destination:Tile));Find.WorldSelector.ClearSelection();Find.WorldSelector.Select(this);}},IncarnateTransit.Icon(IsThunder),true,null,t=>Find.TickManager.Pause());Messages.Message("Choose an empty walkable arrival cell. Canceling retains the traveler with landing and return controls.",MessageTypeDefOf.NeutralEvent,false);}
  public bool TryLand(IntVec3 cell,Map map){if(map==null||map.Tile!=destination||inner.Count!=1||!CelestialLightTravel.LandingSafe(cell,map,IsThunder))return false;Thing placed;Thing passenger=inner[0];if(!inner.TryDrop(passenger,cell,map,ThingPlaceMode.Direct,out placed))return false;var pawn=placed as Pawn;if(pawn!=null)CelestialLightTravel.CompleteArrival(pawn,map,cell,restorePause||Find.TickManager.CurTimeSpeed==TimeSpeed.Paused,draftOnArrival);if(inner.Count==0)Find.WorldObjects.Remove(this);return true;}
  public ThingOwner GetDirectlyHeldThings(){return inner;}
  public void GetChildHolders(List<IThingHolder> children){ThingOwnerUtility.AppendThingHoldersFromThings(children,inner);}
 }
 public sealed class GameComponent_CelestialTravelRecovery:GameComponent {
  public GameComponent_CelestialTravelRecovery(Game game){}
  public override void GameComponentUpdate(){CelestialLightTravel.UpdatePlanning();}
  public override void FinalizeInit(){CelestialLightTravel.ClearPlanningOnLoad();LongEventHandler.ExecuteWhenFinished(()=>{foreach(var obj in Find.WorldObjects.AllWorldObjects.ToArray()){var flight=obj as WorldObject_CelestialLightTravel;if(flight!=null&&flight.automatic&&flight.Container.Count==1)flight.BeginArrival();}});}
 }
 [HarmonyPatch(typeof(GameEnder),"CheckOrUpdateGameOver")]
 public static class CelestialTransitColonyProtection {public static bool Prefix(ref bool ___gameEnding){if(Find.WorldObjects==null)return true;foreach(var world in Find.WorldObjects.AllWorldObjects){var flight=world as WorldObject_CelestialLightTravel;if(flight==null)continue;foreach(var thing in flight.Container){var pawn=thing as Pawn;if(pawn!=null&&!pawn.Dead&&pawn.IsFreeColonist){___gameEnding=false;return false;}}}return true;}}
}
